		isCrewmate: 7,
		isNeutral: 8,
		isImpostorlike: 9,
		nameLength: 11,
		name: 12,
		speakerPositionX: 76,
		speakerPositionY: 80,
		colorR: 84,
		colorG: 88,
		colorB: 92,
		bodyRateX: 96,
		bodyRateY: 100,
		isJammed: 104,
		bodyType: 108,
		neckLength: 112,
